    raise ValueError("data by values must match the report groups")

records: dict[
    tuple[str, str],
    tuple[
        tuple[Decimal, Decimal, Decimal],
        dict[str, tuple[Decimal, Decimal, Decimal]],
    ],
] = {}
for by, key, _picks in groups:
    value = data[(by, key)]
    if not isinstance(value, tuple) or len(value) != 2:
        raise ValueError("data values must be (base, effects) tuples")
    base, effects = value

    def _triple(raw: object, label: str):
        if (
            not isinstance(raw, tuple)
            or len(raw) != 3
        ):
            raise ValueError(f"{label} must be a (uhi, energy, vent) tuple")
        return tuple(
            _validate_finite_number(component, label)
            for component in raw
        )

    base_triple = _triple(base, "base")
    if not isinstance(effects, dict) or set(effects) != set(
        _INTERVENTION_KINDS
    ):
        raise ValueError(
            "effects keys must be exactly green, roof and material"
        )
    effect_triples = {
        kind: _triple(effects[kind], "effect")
        for kind in _INTERVENTION_KINDS
    }
    records[(by, key)] = (base_triple, effect_triples)

with localcontext() as ctx:
    ctx.prec = _MODEL_PRECISION
    ctx.rounding = ROUND_HALF_EVEN

    group_tokens: list[str] = []
    for by, key, picks in groups:
        base_triple, effect_triples = records[(by, key)]
        change = [Decimal(0), Decimal(0), Decimal(0)]
        for kind in picks:
            effect = effect_triples[kind]
            for index in range(3):
                change[index] += effect[index]
        post = [
            base_triple[index] + change[index] for index in range(3)
        ]

        pick_token = "[" + ",".join(
            json.dumps(kind, ensure_ascii=False) for kind in picks
        ) + "]"

        def _metric_token(index: int) -> str:
            return (
                "["
                + _format6(base_triple[index])
                + ","
                + _format6(post[index])
                + ","
                + _format6(change[index])
                + "]"
            )

        group_tokens.append(
            '{"by":' + json.dumps(by, ensure_ascii=False)
            + ',"items":['
            + '{"key":' + json.dumps(key, ensure_ascii=False)
            + ',"pick":' + pick_token
            + ',"uhi":' + _metric_token(0)
            + ',"energy":' + _metric_token(1)
            + ',"vent":' + _metric_token(2)
            + "}]"
        )

return (
    '{"alpha":' + _format6(alpha)
    + ',"groups":[' + ",".join(group_tokens) + "]}\n"
)

